import 'package:fl_chart/fl_chart.dart';
import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../services/app_state.dart';

class AnalyticsScreen extends StatelessWidget {
  const AnalyticsScreen({super.key});
  @override Widget build(BuildContext context) => Consumer<AppState>(builder: (context, state, _) {
    final entries = state.minutesBySubject.entries.toList();
    final maxY = entries.isEmpty ? 60.0 : (entries.map((e) => e.value).reduce((a,b) => a > b ? a : b) * 1.2).toDouble();
    return ListView(padding: const EdgeInsets.all(16), children: [Text('Your progress', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 12), Row(children: [Expanded(child: _Stat(label: 'Study minutes', value: '${state.totalStudyMinutes}')), const SizedBox(width: 10), Expanded(child: _Stat(label: 'Topics done', value: '${state.completedTopics}')), const SizedBox(width: 10), Expanded(child: _Stat(label: 'Journal entries', value: '${state.journals.length}'))]), const SizedBox(height: 18), Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [const Text('Study time by subject', style: TextStyle(fontWeight: FontWeight.bold)), const SizedBox(height: 18), if (entries.isEmpty) const Padding(padding: EdgeInsets.all(24), child: Center(child: Text('Complete a focus session to see your chart.'))) else SizedBox(height: 240, child: BarChart(BarChartData(maxY: maxY, gridData: const FlGridData(show: true), borderData: FlBorderData(show: false), titlesData: FlTitlesData(topTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)), rightTitles: const AxisTitles(sideTitles: SideTitles(showTitles: false)), bottomTitles: AxisTitles(sideTitles: SideTitles(showTitles: true, getTitlesWidget: (value, meta) { final i = value.toInt(); if (i < 0 || i >= entries.length) return const SizedBox.shrink(); return Padding(padding: const EdgeInsets.only(top: 8), child: Text(entries[i].key, style: const TextStyle(fontSize: 9))); })), leftTitles: const AxisTitles(sideTitles: SideTitles(showTitles: true, reservedSize: 35))), barGroups: [for (var i = 0; i < entries.length; i++) BarChartGroupData(x: i, barRods: [BarChartRodData(toY: entries[i].value.toDouble(), width: 18, borderRadius: BorderRadius.circular(5))])])))]))), const SizedBox(height: 12), const Card(child: Padding(padding: EdgeInsets.all(16), child: Text('Tip: consistency matters more than long sessions. Aim to complete your planned one-hour session on your scheduled study days.')))]);
  });
}
class _Stat extends StatelessWidget { const _Stat({required this.label, required this.value}); final String label, value; @override Widget build(BuildContext context) => Card(child: Padding(padding: const EdgeInsets.all(12), child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(label, style: const TextStyle(fontSize: 11, color: Colors.grey)), const SizedBox(height: 6), Text(value, style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 20))]))); }
